function renderAll(){renderPalette();renderSegments();renderInputs();renderOutputs();renderView();}
document.addEventListener('click',e=>{const p=e.target.closest('[data-project]');if(p){selectedProject=Number(p.dataset.project);renderManager()}const u=e.target.closest('[data-open-unit]');if(u)showWorkspace(Number(u.dataset.openUnit));});$('projectSearch').addEventListener('input',renderManager);$('homeBtn').addEventListener('click',showManager);$('addProject').addEventListener('click',()=>window.showPrototypeEditor?window.showPrototypeEditor():null);$('addUnit').addEventListener('click',()=>window.addPrototypeUnit?window.addPrototypeUnit():null);$('newUnitBtn').addEventListener('click',()=>window.addPrototypeUnit?window.addPrototypeUnit():null);
$('paletteGroups').addEventListener('dragstart',e=>{const item=e.target.closest('.library-item');if(!item)return;dragState={kind:'library',type:item.dataset.type,name:item.dataset.name};e.dataTransfer.setData('text/plain',item.dataset.type)});$('dropzone').addEventListener('dragover',e=>{e.preventDefault();$('dropzone').classList.add('dragover')});$('dropzone').addEventListener('dragleave',e=>{if(!e.currentTarget.contains(e.relatedTarget))$('dropzone').classList.remove('dragover')});$('dropzone').addEventListener('drop',e=>{e.preventDefault();$('dropzone').classList.remove('dragover');if(!dragState)return;const card=e.target.closest('.segment'),target=card?segments.findIndex(s=>s.id===card.dataset.id):segments.length;if(dragState.kind==='library'){const s={id:allocateSegmentId(),type:dragState.type,name:dragState.name,length:500,confirmed:false,model:'',source:'',capacity:'',resistance:''};segments.splice(target,0,s);selectedId=s.id}else{const from=segments.findIndex(s=>s.id===dragState.id);if(from<0)return;const [s]=segments.splice(from,1);let at=target;if(from<target)at--;segments.splice(Math.max(0,at),0,s);selectedId=s.id}dragState=null;renderAll()});
let inputRenderFrame=0;function scheduleInputPreview(){if(inputRenderFrame)return;inputRenderFrame=requestAnimationFrame(()=>{inputRenderFrame=0;renderSegments();renderOutputs();renderView()})}
$('inputGrid').addEventListener('input',e=>{const field=e.target.dataset.field,s=segments.find(x=>x.id===selectedId);if(!field||!s)return;s[field]=e.target.value;if(Array.isArray(s.__displayGeometryDefaults)){s.__displayGeometryDefaults=s.__displayGeometryDefaults.filter(key=>key!==field);if(!s.__displayGeometryDefaults.length)delete s.__displayGeometryDefaults}s.confirmed=false;scheduleInputPreview();$('inputNotice').textContent='输入已修改，需重新确认本段'});$('confirmSegment').addEventListener('click',()=>{const s=segments.find(x=>x.id===selectedId);if(!s)return;if(!s.name||Number(s.length)<=0||!s.source){$('inputNotice').textContent='请填写名称、有效段长与选型来源';return}s.confirmed=true;$('inputNotice').textContent='当前段示意确认完成';renderSegments();renderOutputs()});
$('viewControls').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;view=b.dataset.view;$('viewControls').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderView()});const descriptions={'机组资料':'机组风量、设计工况、截面、限制条件与图纸基本信息将在此阶段统一维护。','检查与复核':'逐段检查输入完整性、段序、接口和图纸信息，再进行整机人工复核。','图纸预览':'正式图纸区域将同步呈现侧视、俯视、端视及输出参数表。当前工作台的视图按钮可先查看几何原型。'};document.querySelectorAll('.stage').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.stage').forEach(x=>x.classList.toggle('active',x===b));const active=b.dataset.stage==='功能段配置';['palette','center','inputs'].forEach(id=>$(id).hidden=!active);$('stagePlaceholder').hidden=active;if(!document.getElementById('placeholderTitle'))$('stagePlaceholder').innerHTML='<div class="card"><h2 id="placeholderTitle"></h2><p id="placeholderText"></p></div>';if(b.dataset.stage!=='机组资料')$('stagePlaceholder').querySelector('.card').hidden=false;$('placeholderTitle').textContent=b.dataset.stage;$('placeholderText').textContent=descriptions[b.dataset.stage]||''}));$('saveBtn').addEventListener('click',()=>alert('DOM 原型未连接项目保存；此操作仅作布局示意。'));$('drawBtn').addEventListener('click',()=>alert('DOM 原型未连接正式出图；请先评审布局与交互。'));showManager();
